import {categoriesForAudience,categoryMatches,parentCategory} from './categories.js';
export function catalogFilterBar(products,filters,esc,brands=[]){
 const tree=categoriesForAudience(filters.audience),parent=tree.find(g=>g.name===parentCategory(filters.category)?.name),groups=parent?[parent]:tree;
 const sizes=[...new Set([...products.filter(p=>p.stock>0&&(!parent||categoryMatches(p.category,parent.name))&&(!filters.audience||p.audience===filters.audience||p.audience==='unisex'&&['men','women'].includes(filters.audience))).flatMap(p=>p.sizes||[]),...(filters.sizes||[])])].sort((a,b)=>a.localeCompare(b,'ru',{numeric:true}));
 const checks=(name,items,selected=[])=>items.map(([value,label])=>`<label class="filter-check"><input type="checkbox" name="${name}" value="${esc(value)}" ${selected.includes(value)?'checked':''}><span>${esc(label)}</span></label>`).join('');
 const block=(label,content)=>`<details class="catalog-filter" name="catalog-filter"><summary>${label}<span aria-hidden="true">⌄</span></summary><div class="catalog-filter-panel">${content}</div></details>`;
 return `<form id="catalog-filters" class="catalog-filter-bar" aria-label="Фильтры каталога"><input type="hidden" name="category" value="${esc(parent?.name||'')}">${block('Цена',`<div class="price-range"><input type="number" name="min" min="0" max="10000000" step="0.01" value="${esc(filters.min||'')}" placeholder="От" aria-label="Цена от"><span>—</span><input type="number" name="max" min="0" max="10000000" step="0.01" value="${esc(filters.max||'')}" placeholder="До" aria-label="Цена до"></div>`)}${block('Размер',checks('sizes',sizes.map(s=>[s,s]),filters.sizes)||'<p>Нет доступных размеров</p>')}${block('Бренд',`<input type="search" class="brand-search" data-brand-search placeholder="Найти бренд" aria-label="Поиск бренда">`+checks('brands',brands.map(b=>[b.id,b.name]),filters.brands)||'<p>Нет брендов</p>')}${block('Для кого',`<label>Раздел<select name="audience">${[['','Все'],['men','Мужское'],['women','Женское'],['kids','Детское'],['unisex','Унисекс']].map(([value,label])=>`<option value="${value}" ${(filters.audience||'')===value?'selected':''}>${label}</option>`).join('')}</select></label>`)}${block('Категория',`<p class="small muted">${esc(parent?.name||'Все категории')} · можно выбрать несколько</p>${groups.map(g=>`<fieldset><legend>${esc(g.name)}</legend>${checks('categories',g.children.map(c=>[c,c]),filters.categories)}</fieldset>`).join('')}`)}${block('Состояние',`<label>Состояние вещи<select name="condition">${[['all','Все вещи'],['new','Новое с биркой'],['used','Б/у']].map(([value,label])=>`<option value="${value}" ${(filters.condition||'all')===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="filter-check"><input type="checkbox" name="sale" ${filters.sale?'checked':''}>Только со скидкой</label>`)}<div class="catalog-filter-buttons"><button type="submit" class="btn">Применить</button><button type="button" class="text-link" data-action="reset-filters">Очистить всё</button></div><p class="form-error" role="alert"></p></form>`;
}
